package com.pulsefit.authservice.error; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.Instant; import java.util.Map; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ResponseStatusException.class) public ResponseEntity<Map<String,Object>> status(ResponseStatusException e,org.springframework.web.context.request.WebRequest r){int s=e.getStatusCode().value();return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now().toString(),"status",s,"message",e.getReason()==null?"Request failed":e.getReason(),"path",r.getDescription(false).replace("uri=","")));} @ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException e,org.springframework.web.context.request.WebRequest r){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now().toString(),"status",400,"message","Validation failed","path",r.getDescription(false).replace("uri=","")));} @ExceptionHandler(Exception.class) public ResponseEntity<Map<String,Object>> other(Exception e,org.springframework.web.context.request.WebRequest r){return ResponseEntity.status(500).body(Map.of("timestamp",Instant.now().toString(),"status",500,"message","Internal server error","path",r.getDescription(false).replace("uri=","")));} }
